+	b.WriteString("###                                           __/ |          ###\n")
+	b.WriteString("###                                          |___/           ###\n")
+	b.WriteString("################################################################\n")
+	b.WriteString("###                                                          ###\n")
+
+	for _, line := range lines {
+		b.WriteString(fmt.Sprintf("###  %-54s  ###\n", line))
+	}
+
+	b.WriteString("###                                                          ###\n")
+	b.WriteString("################################################################")
+
+	log.Warn().Msg(b.String())
